package kronex.fun.display.screens.clickgui.components.implement.window.implement.settings.color.component;
import lombok.RequiredArgsConstructor; import net.minecraft.client.gui.DrawContext; import net.minecraft.client.util.math.MatrixStack; import kronex.fun.features.module.setting.implement.ColorSetting; import kronex.fun.other.utils.display.shape.ShapeProperties; import kronex.fun.other.utils.math.MathUtil; import kronex.fun.display.screens.clickgui.components.AbstractComponent; import static net.minecraft.util.math.MathHelper.clamp;
@RequiredArgsConstructor public class SaturationComponent extends AbstractComponent {private final ColorSetting setting;private boolean saturationDragging;private float X,Y,W,H;public void render(DrawContext context,int mouseX,int mouseY,float delta){MatrixStack matrix=context.getMatrices();X=x+6;Y=y+73.5F;W=138;H=4;float clampedX=clamp((float)(X+W*setting.getHue()),X,X+W-4);float min=clamp((float)((mouseX-X)/W),0F,1F);image.setTexture("textures/hue.png").render(ShapeProperties.create(matrix,X,Y+0.5F,W,H-1).build());rectangle.render(ShapeProperties.create(matrix,clampedX,Y,H,H).round(H/2).thickness(3).color(0x00FFFFFF).outlineColor(0xFFFFFFFF).build());if(saturationDragging)setting.setHue(min);}public boolean mouseClicked(double mouseX,double mouseY,int button){saturationDragging=button==0&&MathUtil.isHovered(mouseX,mouseY,X,Y,W,H);return super.mouseClicked(mouseX,mouseY,button);}public boolean mouseReleased(double mouseX,double mouseY,int button){saturationDragging=false;return super.mouseReleased(mouseX,mouseY,button);}}